 private void safe(Runnable action){if(!unlock.isOpen())return;if(web.getUrl()==null){action.run();return;}web.evaluateJavascript("Boolean(window.__alphaNativePosting || window.__alphaNativeBusy && window.__alphaNativeBusy())",value->{if("true".equals(value))say("입력·저장 중인 내용이 있어 화면 전환을 보류합니다. 저장 후 다시 연결합니다.");else action.run();});}
 private void bootstrap(){if(destroyed||!unlock.isOpen()||bootBusy||base.isEmpty()||!UrlPolicy.sameOrigin(web.getUrl(),base))return;bootBusy=true;final long epoch=authEpoch.current();final String endpoint=base,cookie=CookieManager.getInstance().getCookie(base);io.execute(()->{try{Net.Response r=Net.request("GET",endpoint+"/native-admin/bootstrap?device="+store.device(),cookie,null);if((r.status==401||r.status==303)&&!store.flag("signed_out")&&PersistentLogin.restore(this,endpoint))r=Net.request("GET",endpoint+"/native-admin/bootstrap?device="+store.device(),CookieManager.getInstance().getCookie(endpoint),null);if(r.status!=200){if(r.status==401||r.status==403||r.status==303){say("아이디와 비밀번호로 로그인해 주세요.");runOnUiThread(()->{if(!destroyed&&authEpoch.accepts(epoch)&&!store.flag("signed_out")&&unlock.isOpen()&&endpoint.equals(base)&&web.getUrl()!=null&&!Uri.parse(web.getUrl()).getPath().endsWith("/login"))web.loadUrl(endpoint+"/login");});}else{say(r.status==404?"회사 PC 프로그램을 관리자 앱 지원 버전으로 업데이트해 주세요.":"서버 연결 상태를 확인하고 있습니다.");if(System.currentTimeMillis()-lastResolve>10000)runOnUiThread(()->safe(()->connect(false)));}return;}JSONObject j=r.json();if(destroyed||!authEpoch.accepts(epoch)||!unlock.isOpen()||store.flag("signed_out"))return;store.put("cookie_name",j.optString("cookie_name"));store.put("csrf_hint",j.optString("csrf"));try{PersistentLogin.enroll(this,endpoint,CookieManager.getInstance().getCookie(endpoint),j.optString("csrf"),j.optString("account_key"),j.optBoolean("persistent_login"));configureFingerprint();}catch(Exception e){say(e.getMessage());}runOnUiThread(()->{if(destroyed||!authEpoch.accepts(epoch)||!unlock.isOpen()||store.flag("signed_out")||!endpoint.equals(base))return;updateHeader(j);csrf=j.optString("csrf");owner=j.optBoolean("owner");account=j.optString("account_key");store.flag("signed_out",false);String version=j.optString("release");if(!serverVersion.isEmpty()&&!version.equals(serverVersion))safe(()->web.reload());serverVersion=version;String username=j.optString("account_username");if(!username.isEmpty())store.put("fingerprint_username",username);store.put("login_label",j.optString("account_label"));updater.check(false);if(!j.optBoolean("ready")){say("로그인됨 · 앱 알림은 회사 PC에서 Firebase 최초 설정이 필요합니다.");return;}if(store.flag("user_disabled")){say("앱 알림 꺼짐 · 앱 메뉴에서 켤 수 있습니다.");return;}try{store.put("firebase",j.getJSONObject("config").toString());FirebaseSetup.initialize(MainActivity.this);}catch(Exception e){say("앱 알림 초기화 실패 · Firebase 설정을 확인해 주세요.");return;}if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED){say("앱 알림 권한이 필요합니다. 앱 메뉴의 알림 설정을 확인해 주세요.");if(!store.flag("permission_asked")){store.flag("permission_asked",true);requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},42);}return;}FirebaseMessaging.getInstance().getToken().addOnCompleteListener(task->{if(destroyed||!authEpoch.accepts(epoch)||!unlock.isOpen()||store.flag("signed_out")||!endpoint.equals(base))return;if(!task.isSuccessful()){say("앱 알림 토큰을 준비하지 못했습니다. 인터넷 연결을 확인해 주세요.");return;}enroll(endpoint,CookieManager.getInstance().getCookie(endpoint),csrf,account,task.getResult(),j.optBoolean("registered"));});});}catch(Exception e){say("앱 알림 연결 상태를 확인하지 못했습니다.");}finally{bootBusy=false;}});}
 private void enroll(String endpoint,String cookie,String csrfValue,String accountValue,String token,boolean registered){final long epoch=authEpoch.current();if(store.flag("signed_out")||!unlock.isOpen())return;store.put("fcm_token",token);if(registered&&token.equals(store.get("registered_token"))&&accountValue.equals(store.get("account"))&&!store.secret().isEmpty()){say("로그인됨 · 알파 관리자 앱 알림 수신 중");return;}io.execute(()->{if(!authEpoch.accepts(epoch)||store.flag("signed_out"))return;try{Map<String,String> f=new HashMap<>();f.put("csrf",csrfValue);f.put("device",store.device());f.put("token",token);f.put("name",Build.MANUFACTURER+" "+Build.MODEL);Net.Response r=Net.request("POST",endpoint+"/native-admin/register",cookie,f);if(r.status!=200){say("앱 알림 등록 실패 · 로그인과 회사 PC 푸시 설정을 확인해 주세요.");return;}if(destroyed||!authEpoch.accepts(epoch)||store.flag("signed_out"))return;store.secret(r.json().getString("secret"));store.put("registered_token",token);store.put("account",accountValue);store.put("endpoint",endpoint);say("로그인됨 · 알파 관리자 앱 알림 수신 중");}catch(Exception e){say("앱 알림 연결을 저장하지 못했습니다.");}});}
 private void unregister(){final String endpoint=store.get("endpoint"),secret=store.secret();store.put("registered_token","");if(endpoint.isEmpty()||secret.isEmpty())return;io.execute(()->{try{Map<String,String> f=new HashMap<>();f.put("device",store.device());f.put("secret",secret);Net.request("POST",endpoint+"/native-admin/device-disable",null,f);}catch(Exception ignored){}finally{store.secret("");}});}
 private void menu(){if(!unlock.isOpen()){new AlertDialog.Builder(this).setTitle("알파 관리자").setItems(new String[]{"앱 업데이트 확인","알림 소리·진동 설정","앱 정보"},(d,n)->{if(n==0)updater.check(true);else if(n==1)startActivity(new Intent(Settings.ACTION_APP_NOTIFICATION_SETTINGS).putExtra(Settings.EXTRA_APP_PACKAGE,getPackageName()));else new AlertDialog.Builder(this).setTitle("알파 관리자 1.0.4").setMessage("아이디·비밀번호 또는 ‘지문으로 로그인하기’를 선택해 주세요.").setPositiveButton("확인",null).show();}).show();return;}String[] labels={"새로고침 / 다시 연결","알림 소리·진동 설정","앱 테스트 알림 보내기","회사 PC의 앱 푸시 설정",store.flag("user_disabled")?"앱 알림 켜기":"앱 알림 끄기","앱 정보",store.flag("fingerprint_enabled")?"지문 로그인 끄기":"지문 로그인 켜기","앱 업데이트 확인"};new AlertDialog.Builder(this).setTitle("알파 관리자").setItems(labels,(d,n)->{switch(n){case 0:safe(()->{if(web.getUrl()==null||!UrlPolicy.sameOrigin(web.getUrl(),base))connect(false);else web.reload();});break;case 1:startActivity(new Intent(Settings.ACTION_APP_NOTIFICATION_SETTINGS).putExtra(Settings.EXTRA_APP_PACKAGE,getPackageName()));break;case 2:sendTest();break;case 3:if(owner)safe(()->web.loadUrl(base+"/android-admin-settings"));else say("wssong 계정에서 회사 PC 푸시를 설정해 주세요.");break;case 4:boolean off=!store.flag("user_disabled");store.flag("user_disabled",off);if(off)unregister();else bootstrap();say(off?"앱 알림을 껐습니다.":"앱 알림을 연결합니다…");break;case 5:new AlertDialog.Builder(this).setTitle("알파 관리자 1.0.4").setMessage("아이디·비밀번호 로그인 후 휴대폰 지문으로 열 수 있는 관리자 앱입니다.\n앱 알림은 Firebase 연결 후 사용할 수 있습니다.\n화면·업무 기능은 회사 PC 업데이트로 반영됩니다.").setPositiveButton("확인",null).show();break;case 6:if(!hasSavedLogin()){say("먼저 아이디와 비밀번호로 로그인해 주세요.");break;}if(!store.flag("fingerprint_enabled")&&!AppBiometric.available(this)){say("휴대폰 설정에서 지문을 등록한 후 다시 시도해 주세요.");break;}store.flag("fingerprint_enabled",!store.flag("fingerprint_enabled"));store.flag("fingerprint_configured",true);say(store.flag("fingerprint_enabled")?"로그인 화면에서 ‘지문으로 로그인하기’를 사용할 수 있습니다.":"지문 로그인을 껐습니다. 아이디·비밀번호로 로그인할 수 있습니다.");break;case 7:updater.check(true);break;}}).show();}
 private void sendTest(){if(!unlock.isOpen()||base.isEmpty()||csrf.isEmpty()){say("먼저 로그인해 주세요.");return;}final String endpoint=base,cookie=CookieManager.getInstance().getCookie(base),key=csrf;io.execute(()->{try{Map<String,String> f=new HashMap<>();f.put("csrf",key);f.put("device",store.device());Net.Response r=Net.request("POST",endpoint+"/native-admin/test",cookie,f);say(r.status==200?"테스트 알림을 요청했습니다.":"테스트 요청 실패 · Firebase 연결과 로그인을 확인하세요.");}catch(Exception e){say("테스트 알림을 요청하지 못했습니다.");}});}
