 private void download(String u,String disposition,String mime){if(!UrlPolicy.sameOrigin(u,base)){openExternal(u);return;}if(Build.VERSION.SDK_INT<29&&checkSelfPermission(Manifest.permission.WRITE_EXTERNAL_STORAGE)!=PackageManager.PERMISSION_GRANTED){say("파일 저장 권한을 허용한 뒤 사진 저장을 다시 눌러 주세요.");requestPermissions(new String[]{Manifest.permission.WRITE_EXTERNAL_STORAGE},43);return;}try{String name=URLUtil.guessFileName(u,disposition,mime).replace('\\','_').replace('/','_');if(name.equals(".")||name.equals("..")||name.isEmpty())name="alpha-download";DownloadManager.Request request=new DownloadManager.Request(Uri.parse(u)).setTitle(name).setNotificationVisibility(DownloadManager.Request.VISIBILITY_VISIBLE_NOTIFY_COMPLETED).setDestinationInExternalPublicDir(Environment.DIRECTORY_DOWNLOADS,name);String cookie=CookieManager.getInstance().getCookie(base);if(cookie!=null)request.addRequestHeader("Cookie",cookie);((DownloadManager)getSystemService(DOWNLOAD_SERVICE)).enqueue(request);say("다운로드 폴더에 저장합니다.");}catch(Exception e){say("파일을 저장하지 못했습니다.");}}
